require('./yyb.js'); // 自动同步 yyb_go 存活账号
// name: 幸运星
// cron: 28 10,22 * * *
/**
 *
 *
 * 功能（全部纯 Node 接口调用，无需浏览器 / 真实浏览 / App WebView）：
 *   1. 每日签到（signinandreceive）
 *   2. 自动完成所有 PAGEVIEW 任务（pageview 上报 → RUNNING→FINISH）
 *   3. 自动领取全部已完成任务的奖励（receiveprize）
 *   4. 支持多账号逐个处理
 *   5. 支持青龙通知（sendNotify）
 *
 * ===================== 部署与运行说明 =====================
 *
 * 【目录依赖】本文件所在目录（wxapp/）需包含：
 *   - yyb.js      取码模块（连微信协议服务拉取 login code，必需）
 *   - eleme_assets/   阿里 fireye/AWSC 算法资源，生成 bx-ua/mini-janus 等风控头
 *                     （必需；缺少时 getcode 自动兑换会被风控拦截）
 *   运行前请确保整目录随本脚本一起部署（青龙脚本目录）。
 *
 * 【登录方式】三种，按优先级自动选择：
 *   方式 A（推荐·自动）：WX_ID 配置微信账号 → getCode 取 code → login.do 兑换 Cookie
 *   方式 B（注入）：      ELEME_LOGIN_RESULT=<抓包得到的有效 cookie 或 x-smallstc JSON>
 *   方式 C（兼容旧）：    ELEME_COOKIE=<H5 Cookie>（老用户平滑迁移）
 *
 * 【环境变量】
 *   WX_ID               微信账号标识（openid 或 wxid#备注），多账号换行 或 & 分隔（必填）
 *   WX_SERVER      yyb_go 统一协议服务地址（例如：http://127.0.0.1:18273）
 *   YYB_SERVER     (兼容别名) yyb_go 服务地址
 *   ELEME_APPID         饿了么小程序 AppID，默认 wxece3a9a4c82f58c9（可选）
 *   ELEME_LOGIN_RESULT  直接注入有效登录态（可选，走方式 B）
 *   ELEME_COOKIE        H5 Cookie（可选，走方式 C）
 *
 * 【青龙面板】
 *   1. 配置 WX_ID 等环境变量（见上）。
 *   2. 「脚本管理」上传整个 wxapp 目录。
 *   3. 新建定时任务指向 幸运星.js，任务类型选「node」或 shell 命令：
 *        node 幸运星.js
 *   4. （可选）配置青龙通知渠道，运行结束自动推送结果。
 *
 * 【命令行参数】
 *   --dry          只查询不完成/不领取
 *   --view-ms <ms> 每次浏览模拟时长（默认 30000）
 *   --only <id>    仅处理指定 missionDefId
 *   --no-notify    禁用通知
 *   --dump         把任务快照与每次领奖尝试落盘到 wxapp/luckystar_dump_<ts>.json（排错用）
 */
'use strict';

/* =====================================================================
 * 第 1 部分：饿了么 mtop 纯算核心（内联，避免青龙 require 本地模块）
 * ===================================================================== */
const crypto = require('crypto');
const https = require('https');
const { getSingleCode } = require('./yyb.js');

const DEFAULT_CONFIG = {
  appKey: '12574478',
  ua: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E148 AliApp(TB/10.59.40) WindVane/8.7.2',
  referer: 'https://tb.ele.me/app/TBTakeout/engage-hub/home',
  bizScene: 'interact_center',
  accountPlan: 'HAVANA_COMMON',
  // 经纬度真机是「字符串」形态，locationInfos 内部的 lng/lat 同样是字符串。
  // 这里保持字符串，确保 commonParams 生成的 data 与真机抓包完全同构。
  longitude: '119.842406',
  latitude: '31.276809',
  missionCollectionId: 3112,
  // 任务事件上报的风控场景值。来源：App 反编译
  // me/ele/shopdetailv2/header/widget/navigator/i.java#p() -> riskScene = "duobao_external"
  riskScene: 'duobao_external',
  client: 'eleme',
  ASAC: {
    PAGEVIEW: 'alscFS8BNTO6jivYS7XOAM',
    // 任务领奖 mtop.ele.biz.growth.task.core.receiveprize 的风控场景值。
    // 来源（静态逆向）：淘宝闪购 12.8.88 (me.ele) 内置离线包
    //   assets/zcache-preset_sgyx-next.zip → sgyx-next~weex21/1311552/res/*home
    //   其中明文写着 "mtop.ele.biz.growth.task.core.receiveprize,alscPlhUdkIEoklk01xaLW"
    // 旧值 alscadOjfleDPawx9zVoT0 是签到组件的场景值，拿来做任务领奖属于场景串号，会被风控判失败
    // （表现就是 RECEIVE_MISSION_REWARD_RECEIVE_ALL_ERROR）。
    PRIZE: 'alscPlhUdkIEoklk01xaLW',
    // 旧的任务领奖 asac，探测全部失败时作为最后兜底轮换
    PRIZE_LEGACY: 'alscadOjfleDPawx9zVoT0',
    SIGNIN: 'alsc3Lhy681SA5TT4iHgL3',
    // 签到领奖组件 mtop.alsc.interact.playapp.signin.component.receiveprize 的场景值
    SIGNIN_PRIZE: 'alscadOjfleDPawx9zVoT0',
    EXCHANGE: 'alsc5KvbdX5mHl3sdv4guV',
    // event.trigger 的 asac 埋点头，硬编码于 i.java#p()
    TRIGGER: '2A21607NIIT1ND5C4YXJ6C'
  },
  // c.java#e() 中 event.trigger 使用的是 alscec 头（另一套风控埋点）
  ALSCEC_TRIGGER: 'alsclarBlqjTJnvbrII23s'
};

class EleMtop {
  constructor(cookieStr, config = {}) {
    this.cfg = { ...DEFAULT_CONFIG, ...config };
    // 清理 Cookie：去除所有换行/回车/多余空白，避免 HTTP header 报错
    this.cookieJar = (cookieStr || '').replace(/[\r\n\t]+/g, '; ').replace(/;+/g, ';').replace(/\s*;\s*/g, '; ').replace(/;\s*$/, '').trim();
    this._tokenRefreshed = false;
  }

  getCookie(name) {
    const m = new RegExp('(?:^|;\\s*)' + name + '=([^;]*)').exec(this.cookieJar);
    return m ? decodeURIComponent(m[1]) : '';
  }
  _absorbSetCookie(arr) {
    if (!arr) return;
    for (const sc of arr) {
      const first = sc.split(';')[0];
      const eq = first.indexOf('=');
      if (eq <= 0) continue;
      const name = first.slice(0, eq).trim();
      const val = first.slice(eq + 1).trim();
      this.cookieJar = this.cookieJar.replace(new RegExp('(?:^|;\\s*)' + name + '=[^;]*'), '');
      this.cookieJar = (this.cookieJar.replace(/^;|;$/g, '').replace(/;;+/g, ';') + '; ' + name + '=' + val).trim();
    }
  }
  setCookie(str) { this.cookieJar = str; }

  _md5(s) { return crypto.createHash('md5').update(s, 'utf8').digest('hex'); }
  _request(url, headers, method = 'GET', body = null) {
    return new Promise((resolve, reject) => {
      const u = new URL(url);
      const h = { ...headers };
      if (body != null) {
        h['Content-Type'] = 'application/x-www-form-urlencoded';
        h['Content-Length'] = Buffer.byteLength(body);
      }
      const req = https.request(u, { method, headers: h }, (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks).toString('utf8') }));
      });
      req.on('error', reject);
      if (body != null) req.write(body);
      req.end();
    });
  }
  _baseHeaders(extra = {}) {
    return { 'User-Agent': this.cfg.ua, 'Referer': this.cfg.referer, 'Cookie': this.cookieJar, ...extra };
  }

  async refreshToken() {
    // 注意: mtop.common.getTimestamp 不下发 _m_h5_tk, 必须用会 set-cookie 的接口
    // 实测 mtop.alsc.user.session.ele.check 会下发 _m_h5_tk/_m_h5_tk_enc
    const t = Date.now();
    const sign = this._md5(`-1&${t}&${this.cfg.appKey}&{}`);
    const url = `https://waimai-guide.ele.me/h5/mtop.alsc.user.session.ele.check/1.0/?jsv=2.7.5&appKey=${this.cfg.appKey}&t=${t}&sign=${sign}&api=mtop.alsc.user.session.ele.check&v=1.0&type=originaljson&dataType=json&data=${encodeURIComponent('{}')}`;
    const res = await this._request(url, this._baseHeaders());
    this._absorbSetCookie(res.headers['set-cookie']);
    this._tokenRefreshed = true;
    return this.getCookie('_m_h5_tk');
  }
  async ensureToken() {
    let token = this.getCookie('_m_h5_tk').split('_')[0];
    if (!token || !this._tokenRefreshed) {
      await this.refreshToken();
      token = this.getCookie('_m_h5_tk').split('_')[0];
    }
    return token;
  }

  async call(apiName, data = {}, v = '1.0', headers = {}, method = 'GET') {
    const token = await this.ensureToken();
    const t = String(Date.now());
    const dataStr = JSON.stringify(data);
    const sign = this._md5(`${token}&${t}&${this.cfg.appKey}&${dataStr}`);
    const url = new URL(`https://waimai-guide.ele.me/h5/${apiName}/${v}/5.0/`);
    url.searchParams.set('jsv', '2.7.5');
    url.searchParams.set('appKey', this.cfg.appKey);
    url.searchParams.set('mainDomain', 'ele.me');
    url.searchParams.set('subDomain', 'waimai-guide');
    url.searchParams.set('pageDomain', 'ele.me');
    url.searchParams.set('H5Request', 'true');
    url.searchParams.set('ttid', 'h5@Web_android_11.22.143');
    url.searchParams.set('SV', '5.0');
    url.searchParams.set('type', 'originaljson');
    url.searchParams.set('dataType', 'json');
    url.searchParams.set('timeout', '10000');
    url.searchParams.set('t', t);
    url.searchParams.set('sign', sign);
    let res;
    if (String(method).toUpperCase() === 'POST') {
      // mtop h5 网关 POST：data 放 body，签名算法不变
      const body = 'data=' + encodeURIComponent(dataStr);
      res = await this._request(url.toString(), this._baseHeaders(headers), 'POST', body);
    } else {
      url.searchParams.set('data', dataStr);
      res = await this._request(url.toString(), this._baseHeaders(headers));
    }
    this._absorbSetCookie(res.headers['set-cookie']);
    let json;
    try { json = JSON.parse(res.body); } catch (e) { json = { raw: res.body }; }
    return { status: res.status, json, body: res.body };
  }

  commonParams(extra = {}) {
    return {
      bizScene: this.cfg.bizScene,
      accountPlan: this.cfg.accountPlan,
      longitude: this.cfg.longitude,
      latitude: this.cfg.latitude,
      locationInfos: JSON.stringify([JSON.stringify({ lng: this.cfg.longitude, lat: this.cfg.latitude })]),
      ...extra
    };
  }

  async homepage() {
    return this.call('mtop.alsc.interact.et.interact.center.homepage', this.commonParams());
  }
  async querytask() {
    // 真机该接口的 missionCollectionId 是字符串，且额外带 launchChannels:"[]"
    return this.call('mtop.ele.biz.growth.task.core.querytask', this.commonParams({
      missionCollectionId: String(this.cfg.missionCollectionId),
      launchChannels: '[]'
    }));
  }
  /**
   * 浏览类任务上报。
   *
   * 真机样本（mtl12vdlyB0fXGB9 等 5 条，参数完全同构）：
   *   POST /gw/mtop.ele.biz.growth.task.event.pageview/1.1/
   *   data = accountPlan / actionCode:"PAGEVIEW" / bizScene / collectionId(数字) /
   *          latitude / longitude / locationInfos / missionId(数字) / pageFrom / sync:true
   * 与旧实现的差异（已修正）：
   *   - 真机是 POST，旧实现走 GET；
   *   - asac 只在请求头，data 里不带；
   *   - 真机没有 viewTime 字段。
   */
  async pageview(opt) {
    const data = this.commonParams({
      sync: true,
      collectionId: opt.collectionId || this.cfg.missionCollectionId,
      missionId: opt.missionId,
      pageFrom: opt.pageFrom || 'a2ogi.bx1500380',
      actionCode: opt.actionCode || 'PAGEVIEW'
    });
    return this.call('mtop.ele.biz.growth.task.event.pageview', data, '1.1', { asac: this.cfg.ASAC.PAGEVIEW }, 'POST');
  }

  /**
   * 任务事件上报（THIRD 类任务的真实完成通道）
   *
   * 参数集合完整取自 App 反编译源码：
   *   jadx/out/sources/me/ele/shopdetailv2/header/widget/navigator/i.java#p()
   *   jadx/out/sources/me/ele/homepage/repository/c.java#e()
   *
   * 之前 `缺少业务参数eventId` 的根因：
   *   1) 未传 eventId（源码里被混淆成 com.heytap.mcssdk.constant.b.k = "eventId"）
   *   2) bizScene 传了 interact_center，而源码里 me.ele.address.a.c = "bizScene"
   *      对 THIRD 任务传的是 missionId / 业务场景标识，不是互动中心场景
   *   3) 该接口是 POST + version 1.1，不是 GET
   */
  async eventTrigger(opt) {
    const now = Date.now();
    const missionId = String(opt.missionId);
    const eventId = opt.eventId != null ? opt.eventId : now;
    const data = {
      latitude: this.cfg.latitude,
      longitude: this.cfg.longitude,
      riskScene: opt.riskScene || this.cfg.riskScene,
      // i.java: hashMap.put(me.ele.address.a.c /* bizScene */, parseObject.getString("missionid"))
      bizScene: opt.bizScene || missionId,
      eventType: opt.eventType || 'THIRD',
      eventSubType: opt.eventSubType || 'EVENT_FINISH',
      eventId,
      eventIdemPotent: opt.eventIdemPotent != null ? opt.eventIdemPotent : now,
      eventTime: now,
      triggerType: opt.triggerType || 'SYNC',
      collectionId: String(opt.collectionId || this.cfg.missionCollectionId),
      missionId,
      client: this.cfg.client
    };
    if (opt.missionXId != null) data.missionXId = String(opt.missionXId);
    // i.java: headers -> asac: 2A21607NIIT1ND5C4YXJ6C
    const headers = { asac: this.cfg.ASAC.TRIGGER, alscec: this.cfg.ALSCEC_TRIGGER };
    return this.call('mtop.ele.biz.growth.task.event.trigger', data, '1.1', headers, 'POST');
  }
  /**
   * 领取任务奖励。
   *
   * 参数形态取自真机抓包（4 条不同任务的成功样本 mtl29pwsc2m8JpxO / mtl13jftSteYxuuh /
   * mtl162tykZuKh4UA / mtkvrv0qFO85B4H5，参数完全同构）：
   *   accountPlan / bizScene / longitude / latitude / locationInfos
   *   + missionCollectionId / missionId / count
   * 注意：
   *   - 【2026-09-03 实测修正】count 就是服务端认的「阶段参数」：去掉 count 会直接报
   *     CLIENT_PARAM_STAGE_ERROR::参数错误缺少阶段参数；而商业化-互动(44914003)阶段3 在
   *     count=1 时返回 STAGE_NOT_EXIST_ERROR，count=3 时变成 RECEIVE_ALL_ERROR——说明
   *     count 决定服务端去查哪个阶段。因此多阶段任务必须传 count = stageCount，
   *     旧注释「count 是份数、传 stageCount 会被判无效」是错的，已更正；
   *   - v1.1 实测返回 FAIL_SYS_API_NOT_FOUNDED，接口版本锁定 1.0；   *   - 成功样本一律不带 instanceId；抓包里带 instanceId 的两条返回的都是「已全部领奖」类
   *     错误，没有任何成功证据，因此默认不发，避免多余字段引入不确定性；
   *   - asac 只放在请求头，App 端 data 里并不带它，塞进 data 反而与真机不一致。
   */
  /**
   * 领取任务奖励。
   *
   * 【2026-09-03 实测修正】count 是服务端用来定位「阶段」的字段：去掉 count 会直接返回
   *   CLIENT_PARAM_STAGE_ERROR::参数错误缺少阶段参数；
   * 而商业化-互动(44914003)阶段3 在 count=1 时返回 STAGE_NOT_EXIST_ERROR，
   * count=3（=stageCount）时错误变为 RECEIVE_ALL_ERROR——阶段找对了，只是发奖仍被拒。
   * 因此多阶段任务必须传 count = stageCount。接口版本锁定 1.0（1.1 实测 404）。
   *
   * 历史真机抓包结论（4 条成功样本 mtl29pwsc2m8JpxO 等，参数同构）：
   *   accountPlan/bizScene/longitude/latitude/locationInfos + missionCollectionId/missionId/count；
   * 成功样本一律不带 instanceId，默认仍不带；仅当探测形态「先receivetask」从报名响应
   * 中拿到 instanceId 时才写入。asac 只放在请求头。
   *
   * 探测开关（均以 _ 开头，不会进 data），供 prizeVariants() 自动枚举：
   *   _pre      先调 receivetask 报名并尝试取 instanceId
   *   _noCount  删除 count 字段
   *   _asac     覆盖 asac（旧值兜底轮换）
   *   _method   覆盖 GET/POST
   *   stageCount / missionXId / instanceId / sum 按需要写入 data
   */
  async receiveprize(opt) {
    const o = {
      missionCollectionId: opt.missionCollectionId || this.cfg.missionCollectionId,
      missionId: opt.missionId,
      count: opt.count != null ? opt.count : 1
    };
    if (opt.instanceId) o.instanceId = opt.instanceId;
    if (opt.missionXId != null) o.missionXId = String(opt.missionXId);
    if (opt.stageCount != null) o.stageCount = opt.stageCount;
    if (opt.sum != null) o.sum = opt.sum;
    if (opt._noCount) delete o.count;
    const asac = opt._asac || this.cfg.ASAC.PRIZE;
    return this.call(
      'mtop.ele.biz.growth.task.core.receiveprize',
      this.commonParams(o),
      opt._version || '1.0',
      { asac },
      opt._method || 'GET'
    );
  }
  async receivetask(opt) {
    const o = {
      missionCollectionId: opt.missionCollectionId || this.cfg.missionCollectionId,
      missionId: opt.missionId
    };
    return this.call('mtop.ele.biz.growth.task.core.receivetask', this.commonParams(o));
  }
  async signinandreceive(copyId, actId) {
    const data = this.commonParams({ copyId, actId: actId || '' });
    return this.call('mtop.alsc.interact.playapp.signin.component.signinandreceive', data, '1.0', { asac: this.cfg.ASAC.SIGNIN });
  }
  /**
   * 纯签到（不领奖）。
   *
   * 用于处理 FAIL_BIZ_REWARD_MODE_NOT_SIGNIN_AND_RECEIVE::当前签到模式不支持独立领奖：
   * 该活动的 rewardMode 不是「签到即领奖」，必须签到与领奖分两步。
   */
  async signin(copyId, actId) {
    const data = this.commonParams({ copyId, actId: actId || '' });
    return this.call('mtop.alsc.interact.playapp.signin.component.signin', data, '1.0', { asac: this.cfg.ASAC.SIGNIN });
  }
  /** 签到奖励单独领取（配合 signin 使用） */
  async signinReceivePrize(copyId, actId) {
    const data = this.commonParams({ copyId, actId: actId || '' });
    return this.call('mtop.alsc.interact.playapp.signin.component.receiveprize', data, '1.0', { asac: this.cfg.ASAC.SIGNIN_PRIZE });
  }
}

/* =====================================================================
 * 第 2 部分：青龙兼容封装（环境变量读取 / 多账号 / 通知）
 * ===================================================================== */
const fs = require('fs');
const path = require('path');

// 饿了么小程序 AppID（点餐小程序，须与 getCode/YYB 服务端注册的一致）。
// 注意：算法资源 mor.v.js / awsc_params.cjs 固定使用 wxece3a9a4c82f58c9，默认值必须与此一致；
// 若你的取码服务端注册了不同的 AppID，可通过 ELEME_APPID 环境变量覆盖。
const ELEME_APPID = (process.env.ELEME_APPID || '').trim() || 'wxece3a9a4c82f58c9';
const TOKEN_CACHE_FILE = path.join(__dirname, 'luckystar_token_cache.json');

function getArg(name) {
  const i = process.argv.indexOf(name);
  return i !== -1 ? process.argv[i + 1] : undefined;
}

// 本地测试辅助：--ck <文件> 从文件读 H5 Cookie（不影响青龙环境变量读取）
function readCkFile() {
  const p = getArg('--ck');
  if (!p) return null;
  try {
    return fs.readFileSync(path.resolve(p), 'utf8').trim();
  } catch (e) {
    console.error('[!] 读取 --ck 文件失败:', e.message);
    return null;
  }
}

// 环境变量名优先级（H5 Cookie 兜底模式，青龙推荐 ELEME_COOKIE）
const COOKIE_ENV_KEYS = ['ELEME_COOKIE', 'ELM_COOKIE', 'elemeCookie', 'ELEME_STR', 'COOKIE', 'JD_COOKIE'];

/** 从各种环境变量来源收集原始 H5 Cookie 字符串（可含多账号分隔符） */
function collectEnvCookies() {
  const sources = [];
  if (typeof __ENV__ !== 'undefined') {
    for (const k of COOKIE_ENV_KEYS) if (__ENV__[k]) sources.push(__ENV__[k]);
  }
  try {
    const ql = require('qinglong');
    if (ql && typeof ql.getCookie === 'function') {
      for (const k of COOKIE_ENV_KEYS) { const c = ql.getCookie(k); if (c) sources.push(c); }
    }
  } catch (e) {}
  for (const k of COOKIE_ENV_KEYS) {
    if (process.env[k]) sources.push(process.env[k]);
  }
  return sources;
}

/** 将原始 cookie 字符串按常见多账号分隔符拆分成数组 */
function splitAccounts(raw) {
  if (!raw) return [];
  return raw
    .replace(/\r/g, '')
    .split(/\n|@@|&&|&/)
    .map((s) => s.trim())
    .filter((s) => s && s.includes('=') && s.includes(';'));
}

/** 从 cookie 中提取账号标识（优先 USERID，便于日志区分） */
function accountName(cookie) {
  const m = new RegExp('USERID=([^;]+)').exec(cookie);
  return m ? ('用户' + m[1]) : ('账号' + crypto.createHash('md5').update(cookie).digest('hex').slice(0, 6));
}

/** 读取 WX_ID（微信账号），多账号换行或 & 分隔，支持 wxid#备注 */
async function getWxIds() {
  let raw = '';
  // 优先从 yyb 拉取全部存活账号（不受 WX_ID 过滤，配 N 条只跑 N 个）
  try {
    const online = await new YYBClient().getOnlineAccounts();
    if (online && online.length) {
      raw = online
        .map(acc => {
          const id = acc.openid || acc.wxid || String(acc.id || '');
          const note = acc.nickname || acc.alias || acc.remark || '';
          return id ? `wx:${id}#${note}` : '';
        })
        .filter(Boolean)
        .join('\n');
      console.log(`✅ 从 yyb 服务拉取到 ${online.length} 个存活账号`);
    }
  } catch (e) {
    console.log(`[yyb] 拉取账号列表失败: ${e.message || e}`);
  }
  if (!raw) {
    // 回退：WX_ID 环境变量
    raw = (process.env.WX_ID || '').trim();
  }
  if (!raw) {
    // 兜底：自动从 yyb_go 拉取存活账号
    const auto = await resolveAccounts();
    if (auto && auto.length) raw = auto.join('\n');
  }
  if (!raw) return [];
  return raw
    .split(/[\n&]+/)
    .map((v) => String(v).split('#')[0].trim())
    .filter(Boolean);
}

/** ---- token 缓存（getCode 登录态复用，避免每次跑都重新取码登录）---- */
function readTokenCache() {
  try {
    if (!fs.existsSync(TOKEN_CACHE_FILE)) return {};
    return JSON.parse(fs.readFileSync(TOKEN_CACHE_FILE, 'utf8')) || {};
  } catch (e) { return {}; }
}
function writeTokenCache(cache) {
  try { fs.writeFileSync(TOKEN_CACHE_FILE, JSON.stringify(cache, null, 2), 'utf8'); } catch (e) {}
}

/**
 * 账号对象：区分两种模式。
 *  - 模式 getcode: 由 WX_ID 提供 openid/wxid，登录态通过 getCode 换 Cookie 后缓存
 *  - 模式 cookie:  直接使用 H5 Cookie（老用户 / --ck 本地测试）
 */
async function buildAccounts() {
  const accounts = [];
  const seen = new Set();
  const pushCookie = (c) => {
    if (!c || seen.has(c)) return;
    seen.add(c);
    accounts.push({ mode: 'cookie', cookie: c, label: accountName(c) });
  };
  const pushWxid = (wxid) => {
    if (!wxid || seen.has(wxid)) return;
    seen.add(wxid);
    accounts.push({ mode: 'getcode', wxid, label: wxid });
  };

  const ckFile = readCkFile();
  if (ckFile) for (const c of splitAccounts(ckFile)) pushCookie(c);

  const wxIds = await getWxIds();
  if (wxIds.length) {
    for (const wxid of wxIds) pushWxid(wxid);
  } else {
    // 无 WX_ID 时回退到 H5 Cookie 模式
    for (const raw of collectEnvCookies()) {
      for (const c of splitAccounts(raw)) pushCookie(c);
    }
  }
  return accounts;
}

/**
 * getcode 模式登录：用微信 login code 换饿了么登录态 Cookie。
 *
 * 登录链路（已确认）：code → https://ipassport.ele.me/mini_program/login.do → session → 组装 cookie。
 * login.do 请求体含 authorizationCode={"authorizationCode": 微信code}，返回 content.data 为 session
 * （含 sid/cookie2/SID/user_id/open_id/union_id/sgcookie/munb/UTUSER/st）。
 *
 * 注意：login.do 需要阿里 fireye/AWSC 风控头（bx-ua / mini-janus / bx-umidtoken），
 * 由 eleme_assets/awsc_bridge.cjs（Node 桥）生成。若项目缺少该资源，将退化为
 * ELEME_LOGIN_RESULT 注入模式。
 *
 * 返回：饿了么 Cookie 字符串；失败返回 null。
 */
async function wxCodeToElemeCookie(wxid, code) {
  // 方式一：直接注入抓包得到的完整登录 cookie（最稳，不需要 awsc_bridge）
  const injected = (process.env.ELEME_LOGIN_RESULT || '').trim();
  if (injected) {
    if (injected.includes(';') && /[A-Za-z0-9_]+=[^;]+/.test(injected)) {
      console.log('  [登录] 使用 ELEME_LOGIN_RESULT 注入的登录 Cookie');
      return injected;
    }
    try {
      const obj = JSON.parse(injected);
      return loginResultToCookie(obj);
    } catch (e) {
      throw new Error('ELEME_LOGIN_RESULT 无法解析：需为 cookie 字符串或 x-smallstc JSON');
    }
  }

  // 方式二：走 login.do 自动兑换（需本地 awsc_bridge.cjs 生成风控头）
  const login = await havanaCodeLogin(code);
  if (login.ok) return login.cookie;
  throw new Error('饿了么 code 登录失败：' + login.error);
}

/** 把抓包得到的 x-smallstc / loginResult 对象转成饿了么 cookie 字符串 */
function loginResultToCookie(obj) {
  const map = {
    sid: 'sid', cookie2: 'cookie2', SID: 'SID', st: 'st', sgcookie: 'sgcookie',
    csg: 'csg', UTUSER: 'UTUSER', USERID: 'USERID', user_id: 'user_id',
    unb: 'unb', munb: 'munb', open_id: 'open_id', union_id: 'union_id',
    loginSucResultAction: 'loginSucResultAction', loginType: 'loginType',
    loginScene: 'loginScene', appEntrance: 'appEntrance', resultCode: 'resultCode',
    smartlock: 'smartlock', snsType: 'snsType', bindTag: 'bindTag', expires: 'expires',
    elemeExt: 'elemeExt', loginResult: 'loginResult'
  };
  const parts = [];
  for (const [k, ck] of Object.entries(map)) {
    if (obj[k] !== undefined && obj[k] !== null) {
      const val = typeof obj[k] === 'object' ? JSON.stringify(obj[k]) : String(obj[k]);
      parts.push(`${ck}=${encodeURIComponent(val)}`);
    }
  }
  return parts.join('; ');
}

