let ELEME_ASSETS_DIR = path.join(__dirname, 'eleme_assets');
let AWSC_BRIDGE = path.join(ELEME_ASSETS_DIR, 'awsc_bridge.cjs');

/** 若本地 eleme_assets 缺失但有内嵌资源，则自解包到临时目录 */
function ensureElemeAssetsDir() {
  if (fs.existsSync(AWSC_BRIDGE)) return ELEME_ASSETS_DIR;
  const keys = Object.keys(INLINE_ELEME_ASSETS);
  if (!keys.length) return ELEME_ASSETS_DIR;
  const os = require('os');
  const tmpDir = path.join(os.tmpdir(), 'luckystar_eleme_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
  for (const rel of keys) {
    const target = path.join(tmpDir, rel);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, Buffer.from(INLINE_ELEME_ASSETS[rel], 'base64'));
  }
  ELEME_ASSETS_DIR = tmpDir;
  AWSC_BRIDGE = path.join(tmpDir, 'awsc_bridge.cjs');
  console.log(`  [算法资源] 已从内嵌资源自解包到 ${tmpDir}`);
  return tmpDir;
}

const URI_SAFE = new Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()");
const FORM_SAFE = new Set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789*-._');
function pct(s, safeSet, spaceChar) {
  let out = '';
  for (const ch of String(s)) {
    if (ch === ' ') out += spaceChar;
    else if (safeSet.has(ch)) out += ch;
    else {
      for (const b of Buffer.from(ch, 'utf8')) out += '%' + b.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return out;
}
function encUriComponent(s) { return pct(s, URI_SAFE, '%20'); }
function formEncode(pairs) {
  return Object.entries(pairs).map(([k, v]) => `${pct(k, FORM_SAFE, '+')}=${pct(v, FORM_SAFE, '+')}`).join('&');
}
function buildAccountCookie(session) {
  session = session || {};
  const parts = [];
  for (const [outKey, srcKeys] of ACCOUNT_COOKIE_FIELDS) {
    let value = null;
    for (const sk of srcKeys) {
      const v = session[sk];
      if (v !== undefined && v !== null && String(v) !== '') { value = v; break; }
    }
    if (value === null) continue;
    if (outKey === 'SID') parts.push(`${outKey}=${value}`); // SID 不编码
    else parts.push(`${outKey}=${encUriComponent(String(value))}`);
  }
  return parts.join('; ');
}

// 调用本地 awsc_bridge.cjs 生成 bx-ua/mini-janus/bx-umidtoken
// fireyejs(getFYToken) 初始化偶发失败（"人机组件不存在"），故失败时自动重试若干次。
async function buildAwscParams(url, session = {}, umidToken = '') {
  ensureElemeAssetsDir();
  const bridge = AWSC_BRIDGE;
  if (!fs.existsSync(bridge)) {
    return { ok: false, error: `缺少 ${bridge}（awsc_bridge.cjs），无法生成 bx-ua/mini-janus，请放置 eleme_assets 资源或用 ELEME_LOGIN_RESULT 注入` };
  }
  // umidtoken 持久化复用：未显式传入时，复用本地缓存的上次 umid（阿里风控中 umid 是设备级、应长期稳定，
  // 每次重新生成会造成设备指纹漂移，更容易触发 snsBind 绑定风控）
  if (!umidToken) {
    const _cache = readTokenCache();
    if (_cache.awscUmidToken) umidToken = _cache.awscUmidToken;
  }
  const { execFile } = require('child_process');
  const maxRetries = 3;
  let lastErr = '';
  // fireyejs/mor.v 在部分 Node 版本（如 v24）下生成 bx-ua 会报"人机组件不存在/异常"，
  // 可用 ELEME_NODE 指定一个兼容 Node（如 Node 18）运行算法桥。参考 eleme.py 的 ELEME_NODE 设计。
  const nodeBin = (process.env.ELEME_NODE || '').trim() || 'node';
  // 环境诊断：失败时输出，帮助定位青龙 Node 差异
  const envDiag = (() => {
    try {
      const c = require('crypto');
      return `node=${process.version} webcrypto=${typeof c.webcrypto !== 'undefined'} randomUUID=${typeof c.randomUUID === 'function'}`;
    } catch (e) { return `node=${process.version} crypto-err`; }
  })();

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const argsTmp = path.join(ELEME_ASSETS_DIR, `_awsc_args_${Date.now()}_${attempt}.json`);
    const outTmp = path.join(ELEME_ASSETS_DIR, `_awsc_out_${Date.now()}_${attempt}.json`);
    try {
      const args = { url, session, umidToken, debug: false, noNetwork: false };
      fs.writeFileSync(argsTmp, JSON.stringify(args));
      let stderr = '';
      await new Promise((resolve, reject) => {
        execFile(nodeBin, [bridge, argsTmp, outTmp], { cwd: ELEME_ASSETS_DIR, timeout: 90000, maxBuffer: 1024 * 1024 * 20 },
          (err, stdout, stderrBuf) => { stderr = String(stderrBuf || ''); err ? reject(err) : resolve(); });
      });
      if (!fs.existsSync(outTmp)) {
        lastErr = `awsc_bridge 无输出文件${stderr ? '：' + stderr.trim().slice(0, 200) : ''}`;
        if (attempt < maxRetries) { await sleep(1500 * attempt); continue; }
        return { ok: false, error: lastErr };
      }
      const result = JSON.parse(fs.readFileSync(outTmp, 'utf8'));
      if (result && typeof result === 'object') {
        // 生成成功
        if (result.ok) {
          // 持久化最新 umidtoken，供后续登录复用（保持设备指纹稳定）
          const newUmid = result.params && result.params.bxUmidToken;
          if (newUmid) {
            const _cache = readTokenCache();
            if (_cache.awscUmidToken !== newUmid) {
              _cache.awscUmidToken = newUmid;
              writeTokenCache(_cache);
            }
          }
          return result;
        }
        // 部分缺失：优先重试补齐；若失败，返回完整 result（参考 eleme.py：带已生成的头继续尝试）
        const p = result.params || {};
        const miss = [];
        if (!p.miniJanus) miss.push('mini-janus(getSign)');
        if (!p.bxUa) miss.push('bx-ua(getFYToken)');
        if (!p.bxUmidToken) miss.push('bx-umidtoken(mu.json/umid)');
        let detail = result.error || '';
        if (stderr) detail += (detail ? '；' : '') + 'stderr:' + stderr.trim().slice(0, 300);
        lastErr = `算法参数部分未生成（缺少:${miss.join(',') || '未知'}）${detail ? '：' + detail : ''}；环境[${envDiag}]` +
          (miss.includes('bx-ua(getFYToken)') ? '；提示：当前 Node 生成 bx-ua 失败，可设置 ELEME_NODE 指向兼容 Node(如 Node 18) 后再试' : '');
        // 若 bx-ua 缺失（fireyejs 初始化失败），重试；否则（仅缺 umid）不再重试
        if (!p.bxUa && attempt < maxRetries) { await sleep(1500 * attempt); continue; }
        return { ...result, error: lastErr };
      }
      lastErr = 'awsc_bridge 输出格式异常';
    } catch (e) {
      lastErr = `awsc_bridge 调用失败：${e.message}`;
      if (attempt < maxRetries) { await sleep(1500 * attempt); continue; }
    } finally {
      try { fs.unlinkSync(argsTmp); } catch (e) {}
      try { fs.unlinkSync(outTmp); } catch (e) {}
    }
  }
  return { ok: false, error: lastErr };
}

// code -> login.do -> session -> cookie
async function havanaCodeLogin(code) {
  const awsc = await buildAwscParams(LOGIN_ENDPOINT, {}, '');
  const awscOk = !!awsc.ok;
  const params = awsc.params || {};
  const autoUmid = params.bxUmidToken || '';

  const authorizationCode = JSON.stringify({ authorizationCode: code });
  const requestData = {
    type: 'weixin_mini_program',
    appId: ELEME_APPID,
    appName: 'eleme',
    appEntrance: 'weixin',
    lang: 'zh_CN',
    isMobile: true,
    returnUrl: '',
    needPassWebViewCookie: false,
    authorizationCode: authorizationCode
  };
  // 注意：真实抓包请求体不含 umidToken，umid 通过 bx-umidtoken 请求头传递；
  // 与真实请求保持一致，不在 body 中附带 umidToken
  const body = formEncode(requestData);

  const headers = {
    'Accept': 'application/json,text/plain,*/*',
    'Content-Type': 'application/x-www-form-urlencoded',
    'Accept-Language': 'zh-CN,zh;q=0.9',
    'User-Agent': ELEME_UA,
    'Referer': ELEME_REFERER,
    'x-tap': 'wx',
    // 补齐真实微信小程序 webview 的请求指纹头，降低被风控判定为“非真实小程序请求”的概率
    'xweb_xhr': '1',
    'Sec-Fetch-Site': 'cross-site',
    'Sec-Fetch-Mode': 'cors',
    'Sec-Fetch-Dest': 'empty'
  };
  for (const [k, v] of Object.entries(awsc.headers || {})) {
    if (v !== undefined && v !== null && v !== '') headers[k] = String(v);
  }

  const res = await new Promise((resolve, reject) => {
    const u = new URL(LOGIN_ENDPOINT);
    const req = https.request(u, { method: 'POST', headers }, (r) => {
      const c = [];
      r.on('data', (d) => c.push(d));
      r.on('end', () => resolve({ status: r.statusCode, body: Buffer.concat(c).toString('utf8') }));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });

  let j = null;
  try { j = JSON.parse(res.body); } catch (e) { j = null; }
  let contentData = {};
  if (j && j.content && typeof j.content === 'object' && j.content.data && typeof j.content.data === 'object') {
    contentData = j.content.data;
  }
  const session = { ...contentData };
  if (session.sid && !session.cookie2) session.cookie2 = session.sid;
  const cookie = buildAccountCookie(session);
  const ok = res.status >= 200 && res.status < 300 && !!(session.cookie2 || session.sid || session.st);

  let err = '';
  if (!ok) {
    if (!j) err = `接口未返回 JSON（HTTP ${res.status}）`;
    else if (j.hasError) err = `接口错误：${(j.content && (j.content.errorMsg || j.content.msg)) || j.msg || '未知错误'}`;
    else if (contentData.titleMsg) err = `业务错误：${contentData.titleMsg}`;
    else if (['redirect', 'iframeRedirect', 'redirectUrl', 'iframeRedirectUrl'].some((k) => contentData[k])) err = '返回跳转/核身/绑定流程，未直接下发 cookie（可能触发风控或需绑定）';
    else err = `登录未成功：响应无 sid/st/cookie2（HTTP ${res.status}）`;
    if (!awscOk) err += `；且算法参数(bx-ua)未生成：${awsc.error || '未知'}`;
  }

  return { ok, status: res.status, error: err, cookie, session, username: session.username || '', xSmallstc: JSON.stringify(session) };
}

/** 把抓包得到的 x-smallstc / loginResult 对象转成饿了么 cookie 字符串 */
function loginResultToCookie(obj) {
  const map = {
    sid: 'sid', cookie2: 'cookie2', SID: 'SID', st: 'st', sgcookie: 'sgcookie',
    csg: 'csg', UTUSER: 'UTUSER', USERID: 'USERID', user_id: 'user_id',
    unb: 'unb', munb: 'munb', open_id: 'open_id', union_id: 'union_id',
    loginSucResultAction: 'loginSucResultAction', loginType: 'loginType',
    loginScene: 'loginScene', appEntrance: 'appEntrance', resultCode: 'resultCode',
    smartlock: 'smartlock', snsType: 'snsType', bindTag: 'bindTag', expires: 'expires',
    elemeExt: 'elemeExt', loginResult: 'loginResult'
  };
  const parts = [];
  for (const [k, ck] of Object.entries(map)) {
    if (obj[k] !== undefined && obj[k] !== null) {
      const val = typeof obj[k] === 'object' ? JSON.stringify(obj[k]) : String(obj[k]);
      parts.push(`${ck}=${encodeURIComponent(val)}`);
    }
  }
  return parts.join('; ');
}

/**
 * 校验登录态是否仍有效（调用首页接口，未登录会返回 FAIL_BIZ_NOT_LOGIN）。
 * 返回 true 表示有效；false 表示已失效需重新登录。
 */
async function isCookieValid(cookie) {
  try {
    const m = new EleMtop(cookie);
    const hp = await m.homepage();
    const code = retCode(hp.json);
    return code.startsWith('SUCCESS');
  } catch (e) {
    return false;
  }
}

/**
 * 取单个 getcode 账号的登录 Cookie。
 * 优先读缓存；缓存失效（登录态过期）或取码失败则通过 getCode + wxCodeToElemeCookie 重新登录。
 */
async function getCookieForWxid(wxid) {
  // 1. 读缓存
  const cache = readTokenCache();
  const cached = cache[wxid];
  if (cached && cached.cookie) {
    // 1.1 校验缓存登录态是否仍有效，避免一直用失效 Cookie 导致 FAIL_BIZ_NOT_LOGIN
    const valid = await isCookieValid(cached.cookie);
    if (valid) {
      console.log(`  [${wxid}] 使用缓存的饿了么登录态`);
      return cached.cookie;
    }
    console.log(`  [${wxid}] 缓存的登录态已失效，重新登录...`);
    delete cache[wxid];
    writeTokenCache(cache);
  }
  // 2. 取码
  if (!getSingleCode) {
    throw new Error('未找到 yyb.js，请确认脚本在 wxapp 目录下运行或已安装依赖');
  }
  console.log(`  [${wxid}] 通过 getCode 获取微信 code...`);
  const code = await getSingleCode(ELEME_APPID, wxid);
  if (!code) throw new Error('getCode 获取微信 code 失败');
  // 3. 换登录态
  const cookie = await wxCodeToElemeCookie(wxid, code);
  if (!cookie) throw new Error('微信 code 换饿了么登录态失败');
  // 4. 写缓存
  cache[wxid] = { cookie, updatedAt: new Date().toISOString() };
  writeTokenCache(cache);
  return cookie;
}

/** 收集所有待处理账号，为 getcode 账号解析出登录 Cookie */
async function getAllAccounts() {
  const accounts = await buildAccounts();
  const ready = [];
  for (const acc of accounts) {
    if (acc.mode === 'getcode') {
      try {
        const cookie = await getCookieForWxid(acc.wxid);
        ready.push({ ...acc, cookie });
      } catch (e) {
        console.error(`  [!] 账号 [${acc.wxid}] 登录失败: ${e.message}`);
      }
    } else {
      ready.push(acc);
    }
  }
  return ready;
}

/* =====================================================================
 * 第 3 部分：任务执行逻辑（单账号）
 * ===================================================================== */
function retCode(json) {
  return (json && json.ret && json.ret[0]) || '';
}
/**
 * 取出「已完成但奖励未领」的阶段。
 *
 * 不能只看任务顶层 status/receiveStatus（这是之前一直没自动领奖的根因）：
 *   - 多阶段任务（邀请助力、逛店铺等）顶层长期是 RUNNING，
 *     但已达标的那个 stage 已经是 status=FINISH / rewardStatus=TODO，此时就能领；
 *   - 顶层 receiveStatus=HAVERECEIVED 只表示领过某一阶段，后续阶段仍可领；
 *   - 已发放成功的阶段 rewardStatus=SUCCESS，只认 TODO 即可天然排除重复领取。
 */
function receivableStages(task) {
  const list = task.missionStageDTOS || [];
  const out = [];
  for (const st of list) {
    if (st.status === 'FINISH' && st.rewardStatus === 'TODO') out.push(st);
  }
  // 兜底：接口没下发阶段明细，但整任务已完成待领
  if (!out.length && !list.length && task.status === 'FINISH' && task.receiveStatus === 'TORECEIVE') {
    out.push({ stageCount: task.nextStageCount != null ? task.nextStageCount : 1, rewards: [] });
  }
  return out;
}
function canReceive(task) {
  return receivableStages(task).length > 0;
}
/** 阶段唯一键，用于跨轮次去重，避免重复领取同一阶段 */
function stageKey(task, stage) {
  return task.missionDefId + ':' + (stage.stageCount != null ? stage.stageCount : 1);
}
/** 从 receiveprize 响应里提取实际到账奖励（60幸运星 / …） */
function prizeTitle(json) {
  try {
    return (json.data.rlist || [])
      .map((r) => ((r.uppPrizeResult || {}).materialInfo || {}).title || (r.value != null ? String(r.value) : ''))
      .filter(Boolean)
      .join('、');
  } catch (e) { return ''; }
}
/**
 * 判断任务能否由脚本完成，并返回应走的上报通道。
 *
 * 依据反编译源码，App 侧只有 mtop.ele.biz.growth.task.event.trigger 一个事件上报接口
 * （见 i.java#p() / c.java#e()），event.pageview 是 H5 专用接口且风控更严（会返回 405 行为受限）。
 * 因此：PAGEVIEW 任务优先走 pageview，失败后回落 trigger；THIRD 任务只能走 trigger。
 */
function completeChannel(task) {
  if (task.status !== 'RUNNING') return null;
  const ac = task.actionConfig || {};
  const at = ac.actionType;
  const op = ac.actionValue && ac.actionValue.executeOpportunity;
  if (at === 'PAGEVIEW' && op) return 'PAGEVIEW';
  if (at === 'THIRD') return 'THIRD';
  return null;
}
function canComplete(task) {
  return completeChannel(task) !== null;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** 提取任务上的 missionXId（不同接口字段名不一致，逐个兜底） */
/** 提取任务实例标识（不同接口/版本字段名不一致，逐个兜底） */
function pickMissionXId(task) {
  const keys = ['missionXId', 'missionxid', 'missionInstanceId', 'missioninstanceid', 'instanceId', 'taskInstanceId'];
  for (const k of keys) {
    if (task[k] != null && task[k] !== '') return task[k];
  }
  return null;
}

/** 领奖请求的基础参数（随任务变化） */
function prizeBase(task, stage) {
  // count 实测是服务端用来定位阶段的字段，多阶段任务必须传 stageCount
  const sc = stage && stage.stageCount != null ? stage.stageCount : null;
  const base = { missionId: task.missionDefId, count: sc != null ? sc : 1 };
  if (task.missionCollectionId != null && task.missionCollectionId !== '') base.missionCollectionId = task.missionCollectionId;
  return base;
}

/**
 * 领奖参数候选变体（delta 形式，不含 missionId/missionCollectionId）。
 *
 * 背景：任务已完成（stage.status=FINISH 且 rewardStatus=TODO）但 receiveprize 仍报
 *   RECEIVE_MISSION_REWARD_RECEIVE_ALL_ERROR / RECEIVE_MISSION_REWARD_STAGE_NOT_EXIST_ERROR，
 * 说明「服务端认可的可领参数形态」与默认形态不一致。真机参数由服务端下发的动态渲染
 * 模板决定，离线包里只有接口名和 asac，拼不出完整 data，只能靠探测。
 * 因此在首个待领任务上做一次有节制的探测（变体间隔 1.2s），命中后记为 prizePlan，
 * 后续任务直接复用，不再重复探测。
 */
function prizeDeltaTable(sc, mx, ix) {
  const t = [];
  const push = (name, delta) => t.push({ name, delta });
  // 实测：count 决定阶段，阶段号对了才有资格谈发奖
  push("count=阶段号", {});
  push('count=阶段号+先receivetask', { _pre: 'receivetask' });
  if (mx != null) push("count=阶段号+missionXId", { missionXId: mx });
  if (ix != null) push("count=阶段号+instanceId", { instanceId: ix });
  if (sc != null) push("count=阶段号+stageCount字段", { stageCount: sc });
  push("count=阶段号+POST", { _method: "POST" });
  push("count=阶段号+旧asac兜底", { _asac: DEFAULT_CONFIG.ASAC.PRIZE_LEGACY });
  // 历史真机抓包形态（单阶段任务与上面等价）
  if (sc == null || sc === 1) push("count=1(历史形态)", { count: 1 });
  return t;
}
function prizeVariants(task, stage) {
  const ix = ['instanceId', 'instanceid', 'taskInstanceId', 'missionInstId'].map((k) => task[k]).find((v) => v != null && v !== '');
  return prizeDeltaTable(stage.stageCount != null ? stage.stageCount : null, pickMissionXId(task), ix != null ? ix : null);
}
/** 按方案名重建 delta，保证锁定的方案能正确套用到其它任务/阶段上 */
function prizeDeltaByName(name, task, stage) {
  const hit = prizeVariants(task, stage).filter((v) => v.name === name);
  return hit.length ? hit[0].delta : {};
}

/** 处理单个账号，返回 { ok, done, received, skipped, stars } */
async function runAccount(cookie, opts) {
  const { dry, viewMs, onlyMission, log, dump } = opts;
  const m = new EleMtop(cookie);
  const result = { ok: false, done: 0, received: 0, skipped: 0, stars: null, prizes: [] };

  // 0. 首页：拿任务/签到/余额
  const hp = await m.homepage();
  if (!hp.json.ret || !hp.json.ret[0].startsWith('SUCCESS')) {
    log.error(`首页调用失败: ${retCode(hp.json)}`);
    return result;
  }
  const hd = hp.json.data && hp.json.data.data;
  try { result.stars = hd.property.data.STAR.amount; } catch (e) {}
  log.info(`幸运星余额: ${result.stars}`);

  // 签到
  let signInfo = null;
  try {
    const s = hd.signIn && hd.signIn.data;
    signInfo = {
      status: s && s.status,
      copyId: s && s.extInfo && s.extInfo.copyId,
      actId: s && s.actId
    };
  } catch (e) {}
  log.info(`签到状态: ${signInfo && signInfo.status}`);

  if (!dry && signInfo && signInfo.status !== 'HAS_SIGNIN' && signInfo.copyId) {
    const sr = await m.signinandreceive(signInfo.copyId, signInfo.actId || '');
    let code = retCode(sr.json);
    log.info(`每日签到: ${code}`);
    // 当前活动的 rewardMode 不支持「签到即领奖」，拆成 签到 -> 领奖 两步
    if (code.indexOf('NOT_SIGNIN_AND_RECEIVE') !== -1) {
      try {
        log.info(`   [诊断] 签到组件数据: ${JSON.stringify(hd.signIn && hd.signIn.data)}`);
      } catch (e) {}
      await sleep(600);
      const s1 = await m.signin(signInfo.copyId, signInfo.actId || '');
      code = retCode(s1.json);
      log.info(`  改用独立签到: ${code}`);
      if (code.startsWith('SUCCESS')) {
        await sleep(600);
        const s2 = await m.signinReceivePrize(signInfo.copyId, signInfo.actId || '');
        log.info(`  签到领奖: ${retCode(s2.json)}`);
      }
    }
  } else {
    log.info((signInfo && signInfo.status === 'HAS_SIGNIN') ? '今日已签到，跳过' : (dry ? '干跑模式，跳过签到' : '无签到组件'));
  }

  // 收集任务：cardMission（首页任务卡）+ querytask（任务列表）
  const cardTasks = (hd.cardMission && hd.cardMission.data) || [];
  const qt = await m.querytask();
  if (!qt.json.ret || !qt.json.ret[0].startsWith('SUCCESS')) {
    log.error(`querytask 失败: ${retCode(qt.json)}`);
    return result;
  }
  const mlist = (qt.json.data && qt.json.data.mlist) || [];
  log.info(`首页任务卡: ${cardTasks.length} | 任务列表: ${mlist.length}`);

  // 合并两组任务（去重），作为统一处理集合
  let tasks = [];
  const seen = new Set();
  for (const t of [...cardTasks, ...mlist]) {
    if (seen.has(t.missionDefId)) continue;
    seen.add(t.missionDefId);
    tasks.push(t);
  }

  // 刷新任务快照：重新 querytask + homepage，合并成最新状态
  const refresh = async () => {
    const [q2, h2] = [await m.querytask(), await m.homepage()];
    const fresh = [];
    const s = new Set();
    const push = (arr) => { for (const t of arr || []) { if (!s.has(t.missionDefId)) { s.add(t.missionDefId); fresh.push(t); } } };
    if (h2.json.ret && h2.json.ret[0].startsWith('SUCCESS') && h2.json.data && h2.json.data.data) {
      push(h2.json.data.data.cardMission && h2.json.data.data.cardMission.data);
    }
    if (q2.json.ret && q2.json.ret[0].startsWith('SUCCESS')) push(q2.json.data.mlist);
    return fresh;
  };

  // 阶段A：完成任务（PAGEVIEW 走 event.pageview，THIRD 走 event.trigger）
  log.info('--- [阶段A] 完成任务 ---');
  const completes = tasks.filter(canComplete);
  const nPv = completes.filter((t) => completeChannel(t) === 'PAGEVIEW').length;
  log.info(`  可完成: ${completes.length} (PAGEVIEW ${nPv} / THIRD ${completes.length - nPv})`);
  for (const task of completes) {
    if (onlyMission && String(task.missionDefId) !== String(onlyMission)) continue;
    const name = task.name || task.showTitle || ('任务' + task.missionDefId);
    const channel = completeChannel(task);
    log.info(`▶ 完成 [${name}] (${task.missionDefId}) [${channel}]`);
    if (dry) { result.skipped++; continue; }

    const trigger = async () => {
      const tr = await m.eventTrigger({
        missionId: task.missionDefId,
        collectionId: task.missionCollectionId || undefined,
        missionXId: pickMissionXId(task)
      });
      const c = retCode(tr.json);
      log.info(`   trigger: ${c}${c.startsWith('SUCCESS') ? ' (成功)' : ''}`);
      return c;
    };

    let code;
    if (channel === 'PAGEVIEW') {
      // 真机 pageview 不带 viewTime 字段（5 条样本均无），停留时长体现在「打开页面到上报」
      // 的真实间隔上，所以这里改成上报前等待，最多 3s，避免整轮任务被 --view-ms 拖慢。
      await sleep(Math.min(viewMs, 3000));
      const pv = await m.pageview({ missionId: task.missionDefId });
      code = retCode(pv.json);
      log.info(`   pageview: ${code}${code.startsWith('SUCCESS') ? ' (成功)' : ''}`);
      // 405::行为受限 是 H5 pageview 通道的风控拦截，回落到 App 通道 event.trigger
      if (!code.startsWith('SUCCESS')) {
        await sleep(600);
        code = await trigger();
      }
    } else {
      code = await trigger();
    }
    if (code.startsWith('SUCCESS')) result.done++;
    await sleep(800);
  }

  // 完成后刷新任务状态（无论成功与否都刷新一次，服务端可能异步结算）
  log.info('等待服务端更新任务状态...');
  await sleep(2500);
  tasks = await refresh();

  // 阶段B：领取已完成任务奖励
  // 多阶段任务（邀请助力、逛店铺等）一次调用只能领一个阶段，且服务端要在本阶段领完后
  // 才把下一阶段置为可领，所以这里循环多轮，直到没有新的可领阶段。
  log.info('--- [阶段B] 领取已完成任务奖励 ---');
  const receivedKeys = new Set();
  let prizePlan = null;      // 探测到的可用领奖参数形态（方案名）
  const dumpList = [];       // --dump 时记录每次领奖尝试
  let diagDone = false;      // 只打印一次任务/阶段字段诊断
  for (let round = 1; round <= 5; round++) {
    const pending = [];
    for (const t of tasks) {
      if (onlyMission && String(t.missionDefId) !== String(onlyMission)) continue;
      for (const st of receivableStages(t)) {
        const k = stageKey(t, st);
        if (receivedKeys.has(k)) continue;
        pending.push({ task: t, stage: st });
      }
    }
    if (!pending.length) {
      if (round === 1) log.info('  无待领取奖励');
      break;
    }
    log.info(`  第 ${round} 轮可领取: ${pending.length}`);

    let got = 0;
    for (const { task, stage } of pending) {
      const name = task.name || task.showTitle || ('任务' + task.missionDefId);
      const sc = stage.stageCount != null ? stage.stageCount : 1;
      const reward = (stage.rewards || [])[0];
      const desc = reward ? `${reward.name || ''}+${reward.value}` : '';
      log.info(`★ 领取 [${name}] (${task.missionDefId}) 阶段${sc}${desc ? ' 奖励:' + desc : ''}`);
      receivedKeys.add(stageKey(task, stage));
      if (dry) { result.skipped++; continue; }

      if (!diagDone) {
        log.info(`   [诊断] 任务字段: ${Object.keys(task).join(",")}`);
        log.info(`   [诊断] 阶段字段: ${Object.keys(stage).join(",")}`);
        diagDone = true;
      }
      // 首个待领任务做参数形态探测，命中后记为 prizePlan，后续任务直接复用
      const variants = prizePlan ? [{ name: prizePlan, delta: prizeDeltaByName(prizePlan, task, stage) }] : prizeVariants(task, stage);
      let ok = false;
      for (let vi = 0; vi < variants.length; vi++) {
        const v = variants[vi];
        const extra = Object.assign(prizeBase(task, stage), v.delta);
        // growth 任务平台的标准流程是 receivetask(报名) → 做任务 → receiveprize(领奖)，
        // 脚本此前从未调过 receivetask，这里补上并尝试从响应里取 instanceId
        if (v.delta && v.delta._pre === 'receivetask') {
          delete extra._pre;
          try {
            const rt = await m.receivetask({ missionId: task.missionDefId, missionCollectionId: task.missionCollectionId });
            log.info(`   receivetask: ${retCode(rt.json)}`);
            const rd = rt.json && rt.json.data;
            if (rd) {
              const iid = rd.instanceId != null ? rd.instanceId : (rd.missionXId != null ? rd.missionXId : null);
              if (iid != null) { extra.instanceId = iid; log.info(`   receivetask 返回 instanceId=${iid}`); }
            }
          } catch (e) { log.info(`   receivetask: 异常 ${e.message}`); }
          await sleep(800);
        }
        let rp;
        try {
          rp = await m.receiveprize(extra);
        } catch (e) {
          log.info(`   receiveprize[${v.name}]: 异常 ${e.message}`);
          continue;
        }
        const code = retCode(rp.json);
        const prize = prizeTitle(rp.json);
        if (code.startsWith('SUCCESS')) {
          log.info(`   receiveprize[${v.name}]: ${code} (领取成功${prize ? " → " + prize : ""})`);
          result.received++;
          got++;
          if (prize) result.prizes.push(prize);
          if (!prizePlan) {
            prizePlan = v.name;
            log.info(`   [锁定领奖参数形态] ${v.name} → ${JSON.stringify(v.delta)}`);
          }
          ok = true;
          break;
        }
        log.info(`   receiveprize[${v.name}]: ${code}`);
        if (dump) dumpList.push({ missionDefId: task.missionDefId, stage: sc, variant: v.name, req: Object.assign(prizeBase(task, stage), v.delta), res: rp.json });
        if (vi < variants.length - 1) await sleep(1200);
      }
      if (!ok) result.failed = (result.failed || 0) + 1;
      await sleep(900);
    }
    if (dry || !got) break;
    // 领到过奖励说明状态有变化，刷新看是否解锁了下一阶段
    await sleep(1800);
    tasks = await refresh();
  }

  // --dump：把任务快照与领奖尝试全部落盘，便于和真机抓包逐字段比对
  if (dump) {
    try {
      const dumpFile = path.join(__dirname, 'luckystar_dump_' + String(Date.now()) + '.json');
      fs.writeFileSync(dumpFile, JSON.stringify({ mlist: tasks, receiveAttempts: dumpList }, null, 2));
      log.info(`[dump] 已写入 ${dumpFile}`);
    } catch (e) { log.info(`[dump] 写入失败: ${e.message}`); }
  }

  // 最终余额
  if (!dry) {
    const hp2 = await m.homepage();
    try { result.stars = hp2.json.data.data.property.data.STAR.amount; } catch (e) {}
  }

  result.ok = true;
  return result;
}

/* =====================================================================
 * 第 4 部分：青龙通知
 * ===================================================================== */
function loadQingLongNotify() {
  // 1) 优先项目自带 sendNotify（与仓库其它脚本一致，走环境变量推送，不依赖青龙面板 token，最稳定）
  try {
    const mod = require('../sendNotify');
    if (mod && typeof mod.sendNotify === 'function') return mod.sendNotify;
  } catch (e) {}
  // 2) 回退青龙部署版 sendNotify（部分环境青龙版会因 access_token 缺失报错，故仅作兜底）
  try {
    const mod = require('/ql/scripts/sendNotify.js');
    if (mod && typeof mod.sendNotify === 'function') return mod.sendNotify;
  } catch (e) {}
  try {
    const mod = require('sendNotify');
    if (mod && typeof mod.sendNotify === 'function') return mod.sendNotify;
  } catch (e) {}
  return null;
}

async function sendNotify(title, body) {
  const fn = loadQingLongNotify();
  if (fn) {
    try { await fn(title, body); return; } catch (e) { console.warn('[notify] 发送失败:', e.message); }
  }
  // 无青龙通知渠道则打印到日志
  console.log(`[通知] ${title}`);
  console.log(body);
}

/* =====================================================================
 * 第 5 部分：入口 main（青龙调用 & 命令行直跑）
 * ===================================================================== */
/**
 * 青龙面板会 require 本文件并调用 main()。
 * 也可直接 node qinglong-ele-luckystar.js 运行。
 */
async function main() {
  const dry = process.argv.includes('--dry');
  const noNotify = process.argv.includes('--no-notify');
  const viewMs = parseInt(getArg('--view-ms') || '30000', 10);
  const onlyMission = getArg('--only');
  const dump = process.argv.includes('--dump');

  const accounts = await getAllAccounts();
  if (accounts.length === 0) {
    console.error('[!] 未检测到任何可用账号。');
    console.error('    方式一（推荐）：在青龙「环境变量」中新建 WX_ID，值为微信账号标识');
    console.error('      wxid#备注 或 openid，多账号用 换行 或 & 分隔。');
    console.error('    方式二（H5 Cookie 兼容）：新建 ELEME_COOKIE，值为饿了么 H5 Cookie。');
    console.error('    getcode 模式需在 getCookieForWxid/wxCodeToElemeCookie 中配置饿了么登录接口。');
    process.exitCode = 1;
    return;
  }

  console.log(`[*] 检测到 ${accounts.length} 个账号，模式: ${dry ? '干跑(只查询)' : '自动(完成+领取)'}`);
  const lines = [];
  const summaries = [];

  for (let i = 0; i < accounts.length; i++) {
    const acc = accounts[i];
    const cookie = acc.cookie;
    const name = acc.label || accountName(cookie || '');
    console.log(`\n========== 账号 ${i + 1}/${accounts.length}: ${name} ==========`);
    const log = {
      info: (s) => console.log('  ' + s),
      error: (s) => console.error('  ' + s)
    };
    try {
      const r = await runAccount(cookie, { dry, viewMs, onlyMission, log, dump });
      const status = r.ok ? '成功' : '失败';
      const prize = r.prizes && r.prizes.length ? ` | 奖励 ${r.prizes.join('、')}` : '';
      const line = `${name}: ${status} | 完成 ${r.done} | 领取 ${r.received}${r.failed ? ` | 领奖失败 ${r.failed}` : ""}${prize} | 余额 ${r.stars}`;
      console.log(`  [账号结果] ${line}`);
      lines.push(line);
      summaries.push({ name, ...r });
    } catch (e) {
      console.error(`  [!] 账号处理异常: ${e.message}`);
      lines.push(`${name}: 异常 (${e.message})`);
      summaries.push({ name, ok: false, error: e.message });
    }
  }

  // 汇总
  console.log('\n========== 全部账号汇总 ==========');
  lines.forEach((l) => console.log('  ' + l));

  // 通知
  if (!noNotify) {
    const totalDone = summaries.reduce((s, x) => s + (x.done || 0), 0);
    const totalReceived = summaries.reduce((s, x) => s + (x.received || 0), 0);
    const allOk = summaries.every((x) => x.ok);
    await sendNotify(
      allOk ? '⭐ 闪购幸运星任务完成' : '⚠️ 闪购幸运星任务部分失败',
      [`账号数: ${summaries.length}`, `完成任务: ${totalDone}`, `领取奖励: ${totalReceived}`, '', ...lines].join('\n')
    );
  }

  console.log('\n[全部完成]');
}

// 支持 require 方式（青龙）与直接 node 运行
if (require.main === module) {
  main().catch((e) => { console.error('[!] 致命错误:', e); process.exit(1); });
}

module.exports = { main, EleMtop, getAllAccounts, getWxIds, wxCodeToElemeCookie };